function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 50) return 'words needs 1 to 50 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 10) return 'Each word has 1 to 10 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase English letters only.';
  }
  return null;
}

