function countPrefixSuffixPairs(words) {
  let count = 0;
  for (let j = 0; j < words.length; j++) {
    const word = words[j];
    for (let i = 0; i < j; i++) {
      const piece = words[i];
      if (word.startsWith(piece) && word.endsWith(piece)) {
        count++;
      }
    }
  }
  return count;
}

