function countPrefixSuffixPairs(words) {
  const borders = (s) => {
    const set = new Set();
    for (let len = 1; len <= s.length; len++) {
      if (s.substring(0, len) === s.substring(s.length - len)) set.add(s.substring(0, len));
    }
    return set;
  };
  let pairs = 0;
  for (let a = 0; a < words.length; a++) {
    for (let b = a + 1; b < words.length; b++) {
      if (borders(words[b]).has(words[a])) pairs++;
    }
  }
  return pairs;
}

