function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const count = size === 'large' ? int(45, 50) : int(1, 8);
  const letters = rand() < 0.5 ? 'ab' : rand() < 0.5 ? 'abc' : 'abcdefghijklmnopqrstuvwxyz';
  const maxLen = size === 'large' ? 10 : 4;
  const randomWord = (len) => Array.from({ length: len }, () => letters[int(0, letters.length - 1)]).join('');
  const words = [];
  for (let k = 0; k < count; k++) {
    const choice = rand();
    if (choice < 0.35 && words.length > 0) {
      // Wrap an earlier short word around a middle part so it becomes a prefix and a suffix.
      const piece = words[int(0, words.length - 1)];
      if (piece.length * 2 <= maxLen) {
        const middle = randomWord(int(0, maxLen - piece.length * 2));
        words.push(rand() < 0.3 ? piece : piece + middle + piece);
        continue;
      }
    }
    words.push(randomWord(int(1, rand() < 0.5 ? Math.min(3, maxLen) : maxLen)));
  }
  return [words];
}
